#include "noe.hpp"
#include <cctype>
#include <iostream>
#include <optional>
#include <sstream>
#include <string>
namespace noe { namespace { std::string jsonEscape(const std::string&s){std::ostringstream out;for(unsigned char c:s){switch(c){case'\\':out<<"\\\\";break;case'\"':out<<"\\\"";break;case'\n':out<<"\\n";break;case'\r':out<<"\\r";break;case'\t':out<<"\\t";break;default:if(c<0x20)out<<'?';else out<<static_cast<char>(c);}}return out.str();} std::optional<std::string> jsonString(const std::string&body,const std::string&key){std::string needle="\""+key+"\"";auto p=body.find(needle);if(p==std::string::npos)return std::nullopt;p=body.find(':',p+needle.size());if(p==std::string::npos)return std::nullopt;++p;while(p<body.size()&&std::isspace(static_cast<unsigned char>(body[p])))++p;if(p>=body.size()||body[p]!='\"')return std::nullopt;++p;std::string out;while(p<body.size()){char c=body[p++];if(c=='\"')return out;if(c=='\\'&&p<body.size()){char e=body[p++];switch(e){case'n':out+='\n';break;case'r':out+='\r';break;case't':out+='\t';break;case'\"':out+='\"';break;case'\\':out+='\\';break;case'/':out+='/';break;default:out+=e;}}else out+=c;}return std::nullopt;} std::optional<std::string> rawId(const std::string&body){auto p=body.find("\"id\"");if(p==std::string::npos)return std::nullopt;p=body.find(':',p+4);if(p==std::string::npos)return std::nullopt;++p;while(p<body.size()&&std::isspace(static_cast<unsigned char>(body[p])))++p;if(p>=body.size())return std::nullopt;if(body[p]=='\"'){auto e=p+1;bool esc=false;while(e<body.size()){if(!esc&&body[e]=='\"')return body.substr(p,e-p+1);esc=!esc&&body[e]=='\\';if(body[e]!='\\')esc=false;++e;}return std::nullopt;}auto e=p;while(e<body.size()&&(std::isdigit(static_cast<unsigned char>(body[e]))||body[e]=='-'))++e;return e>p?std::optional<std::string>(body.substr(p,e-p)):std::nullopt;} bool readMessage(std::string&body){std::string line;std::size_t length=0;while(std::getline(std::cin,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty())break;const std::string h="Content-Length:";if(line.rfind(h,0)==0)length=static_cast<std::size_t>(std::stoul(line.substr(h.size())));}if(!std::cin||length==0)return false;body.assign(length,'\0');std::cin.read(body.data(),static_cast<std::streamsize>(length));return static_cast<std::size_t>(std::cin.gcount())==length;} void send(const std::string&body){std::cout<<"Content-Length: "<<body.size()<<"\r\n\r\n"<<body<<std::flush;} void publishDiagnostics(const std::string&uri,const std::string&text){auto result=compileSource(text);std::ostringstream out;out<<"{\"jsonrpc\":\"2.0\",\"method\":\"textDocument/publishDiagnostics\",\"params\":{\"uri\":\""<<jsonEscape(uri)<<"\",\"diagnostics\":[";bool first=true;for(const auto&d:result.diagnostics.items()){if(!first)out<<',';first=false;auto line=d.span.line?d.span.line-1:0;auto col=d.span.column?d.span.column-1:0;out<<"{\"range\":{\"start\":{\"line\":"<<line<<",\"character\":"<<col<<"},\"end\":{\"line\":"<<line<<",\"character\":"<<(col+1)<<"}},\"severity\":1,\"code\":\""<<jsonEscape(d.code)<<"\",\"source\":\"noqeri\",\"message\":\""<<jsonEscape(d.message)<<"\"}";}out<<"]}}";send(out.str());} }
int LanguageServer::run(){bool shutdown=false;std::string body;while(readMessage(body)){auto method=jsonString(body,"method");if(!method)continue;auto id=rawId(body);if(*method=="initialize"){std::string rid=id.value_or("null");send("{\"jsonrpc\":\"2.0\",\"id\":"+rid+",\"result\":{\"capabilities\":{\"textDocumentSync\":1,\"documentFormattingProvider\":false},\"serverInfo\":{\"name\":\"noqeri Language Server\",\"version\":\"1.0.0\"}}}");}else if(*method=="initialized")continue;else if(*method=="shutdown"){shutdown=true;send("{\"jsonrpc\":\"2.0\",\"id\":"+id.value_or("null")+",\"result\":null}");}else if(*method=="exit")return shutdown?0:1;else if(*method=="textDocument/didOpen"||*method=="textDocument/didChange"){auto uri=jsonString(body,"uri");auto text=jsonString(body,"text");if(uri&&text)publishDiagnostics(*uri,*text);}else if(*method=="textDocument/didClose"){if(auto uri=jsonString(body,"uri"))send("{\"jsonrpc\":\"2.0\",\"method\":\"textDocument/publishDiagnostics\",\"params\":{\"uri\":\""+jsonEscape(*uri)+"\",\"diagnostics\":[]}}");}else if(id)send("{\"jsonrpc\":\"2.0\",\"id\":"+*id+",\"result\":null}");}return 0;} }
